-- Keep ingredient JSON category labels aligned with the canonical ingredient catalog.
UPDATE public.recipes AS recipe
SET ingredients = (
  SELECT jsonb_agg(jsonb_set(item.ingredient, '{category}', to_jsonb(canonical.category), true) ORDER BY item.ordinality)
  FROM jsonb_array_elements(recipe.ingredients) WITH ORDINALITY AS item(ingredient, ordinality)
  JOIN public.ingredients AS canonical ON canonical.name = item.ingredient->>'name'
)
WHERE recipe.id IN ('city-cafe-roti-de-porc-et-sauce-charcutiere', 'city-cafe-saute-de-porc-basquaise-au-piment-d-espelette', 'city-cafe-roti-de-veau-facon-grand-mere-et-pommes-nouvelles-confites', 'city-cafe-travers-de-porc-a-la-texane', 'city-cafe-emince-de-veau-a-l-italienne-et-basilic', 'city-cafe-boulettes-d-agneau-a-la-libanaise', 'city-cafe-ribs-de-porc-barbecue-et-pommes-de-terre-roties', 'city-cafe-joue-de-porc-au-cidre-et-lardons-fumes', 'city-cafe-epaule-de-porc-farcie-aux-epinards-et-pruneaux', 'city-cafe-grenadin-de-porc-sauce-moutarde-et-figues', 'city-cafe-pave-de-cheval-et-sauce-bearnaise', 'city-cafe-pave-de-cheval-aux-herbes', 'city-cafe-magret-de-canard-roti-et-jus-balsamique', 'city-cafe-parmentier-de-canard-mousseline-de-celeri-et-morilles', 'city-cafe-filet-de-canard-roti-jus-au-raisin-et-mousseline-de-pomme-de-terre-et-celeri', 'city-cafe-pastilla-de-canard-aux-fruits-secs-miel-et-citron', 'city-cafe-civet-de-cerf-au-cacao-et-spatzle', 'city-cafe-saucisse-de-cerf-a-la-moutarde-airelles-et-spatzle', 'city-cafe-poitrine-de-faisan-au-raisin-et-sauce-aux-morilles', 'city-cafe-gigot-d-agneau-au-miel-curry-et-citron');

